mapper.select:
SELECT DISTINCT u.id, u.username, u.realname, u.role, u.avatar_url AS avatarUrl, u.created_at AS createdAt, u.updated_at AS updatedAt FROM users u
INNER JOIN course_student_rel cs ON u.id = cs.student_id
INNER JOIN task_student_rel ts ON u.id = ts.student_id LEFT JOIN student_submissions ss ON ts.task_id = ss.task_id AND ts.student_id = ss.student_id
u.role = 'student'
AND cs.course_id = #{q.courseId}
AND ts.task_id = #{q.taskId}
AND ss.status = #{q.status}
AND (u.username LIKE CONCAT('%',#{q.keyword},'%') OR u.realname LIKE CONCAT('%',#{q.keyword},'%'))
LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT u.id) FROM users u
INNER JOIN course_student_rel cs ON u.id = cs.student_id
INNER JOIN task_student_rel ts ON u.id = ts.student_id LEFT JOIN student_submissions ss ON ts.task_id = ss.task_id AND ts.student_id = ss.student_id
u.role = 'student'
AND cs.course_id = #{q.courseId}
AND ts.task_id = #{q.taskId}
AND ss.status = #{q.status}
AND (u.username LIKE CONCAT('%',#{q.keyword},'%') OR u.realname LIKE CONCAT('%',#{q.keyword},'%'))
